from collections import deque


def fewest_steps_breaking(grid: list[str], k: int) -> int:
    rows, cols = len(grid), len(grid[0])
    queue, seen = deque([(0, 0, k, 0)]), {(0, 0, k)}
    while queue:
        r, c, left, dist = queue.popleft()
        if (r, c) == (rows - 1, cols - 1):
            return dist
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols:
                after = left - (grid[nr][nc] == "#")   # a wall spends one break
                if after >= 0 and (nr, nc, after) not in seen:
                    seen.add((nr, nc, after))         # the state, not just the cell
                    queue.append((nr, nc, after, dist + 1))
    return -1

