from collections import deque
from itertools import combinations


def fewest_steps_breaking(grid: list[str], k: int) -> int:
    rows, cols = len(grid), len(grid[0])
    walls = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == "#"]
    best = -1
    for used in range(min(k, len(walls)) + 1):
        for broken in combinations(walls, used):  # every choice of walls to break, then plain BFS
            open_cells, queue, seen = set(broken), deque([(0, 0, 0)]), {(0, 0)}
            while queue:
                r, c, dist = queue.popleft()
                if (r, c) == (rows - 1, cols - 1):
                    best = dist if best == -1 else min(best, dist)
                    break
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    inside = 0 <= nr < rows and 0 <= nc < cols
                    if inside and (nr, nc) not in seen and (grid[nr][nc] == "." or (nr, nc) in open_cells):
                        seen.add((nr, nc))
                        queue.append((nr, nc, dist + 1))
    return best
